name: Codex Review - Notify Code Owner

on:
  pull_request:
    types: [opened, reopened, synchronize, ready_for_review]
    branches:
      - main
      - develop

permissions:
  contents: read
  pull-requests: write

jobs:
  notify-code-owner:
    if: github.event.pull_request.draft == false
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Get code owners
        id: codeowners
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const path = require('path');

            // Read CODEOWNERS file
            const codeownersPath = '.github/CODEOWNERS';
            let codeownersContent = '';

            try {
              codeownersContent = fs.readFileSync(codeownersPath, 'utf8');
            } catch (error) {
              console.log(`Failed to read CODEOWNERS: ${error.message}`);
              return { owners: [] };
            }

            // Parse CODEOWNERS entries
            const owners = new Set();
            const lines = codeownersContent.split('\n').filter(line => line.trim() !== '' && !line.startsWith('#'));

            for (const line of lines) {
              const parts = line.trim().split(/\s+/);
              if (parts.length > 1) {
                const filePathPattern = parts[0];
                const ownerList = parts.slice(1);

                // Only consider non-glob patterns for direct file matching
                if (!filePathPattern.includes('*') && !filePathPattern.includes('?') && !filePathPattern.includes('[')) {
                  for (const owner of ownerList) {
                    if (owner.startsWith('@')) {
                      owners.add(owner.substring(1));
                    }
                  }
                }
              }
            }

            // Get PR author
            const prAuthor = context.payload.pull_request.user.login;

            // Filter out PR author from owners
            const filteredOwners = Array.from(owners).filter(owner => owner !== prAuthor);

            return { owners: filteredOwners };

      - name: Notify code owners
        if: steps.codeowners.outputs.owners != '[]'
        uses: actions/github-script@v7
        with:
          script: |
            const owners = JSON.parse('${{ steps.codeowners.outputs.owners }}');
            const prNumber = context.issue.number;
            const prTitle = context.payload.pull_request.title;
            const prUrl = context.payload.pull_request.html_url;
            const prAuthor = context.payload.pull_request.user.login;

            // Format the message
            const message = `@${owners.join(', @')} This PR is ready for review:\n\n**Title:** ${prTitle}\n**Author:** ${prAuthor}\n**Link:** ${prUrl}`;

            // Add comment to PR
            await github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: message
            });
```

